-- Новая программа тренировок: «Full body румынская тяга» (12 тренировок).
--
-- Плюс общая правка карточки программы: название разбивается на две строки —
-- display_name («Full body») крупно и subtitle («румынская тяга») помельче.
-- Раньше всё имя писалось одной строкой и на карточке не помещалось.

-- 1. Вторая строка названия. Колонка нужна ВСЕМ программам, поэтому заводится
--    здесь, а не в отдельной миграции.
alter table program_templates add column if not exists subtitle text;

-- 2. Уже заведённые программы переезжают на две строки. display_name остаётся
--    первой строкой, вторая уезжает в subtitle. В коде одна строка текста
--    (для ИИ-ассистента, заголовков) собирается обратно как display_name + subtitle.
update program_templates
   set display_name = 'Full body', subtitle = 'болгарские выпады', updated_at = now()
 where key = 'full-body-bolgarskie-vypady';

update program_templates
   set display_name = 'Full body', subtitle = 'ягодичный мост', updated_at = now()
 where key = 'full-body-yagodichnyy-most';

-- 3. Единственное упражнение, которого ещё не было в каталоге.
insert into catalog_exercises (name, muscle_group, equipment, type, hidden)
values ('Становая тяга сумо со штангой', 'Ягодицы', 'Штанга', 'compound', false)
on conflict (name) do nothing;

-- 4. Сама программа.
--    Подходы без веса записаны как «× 20» — принятая в шаблонах запись
--    собственного веса (parseTemplateSets отдаёт templateKg = null). «0 кг × 20»
--    писать НЕЛЬЗЯ: ноль пройдёт как настоящий вес и обнулит расчёт 1ПМ.
