on conflict (key) do update set
  display_name = excluded.display_name,
  subtitle     = excluded.subtitle,
  context      = excluded.context,
  icon         = excluded.icon,
  description  = excluded.description,
  structure    = excluded.structure,
  hidden       = false,
  updated_at   = now();

